 // Shared portal data is stored centrally in Supabase so every device sees the same updates.
async function api(action:string,args:any){
 const collection=args.collection;
 if(action==='records.list'){const {data,error}=await supabase.from('portal_records').select('id,value').eq('collection',collection).order('created_at',{ascending:false});if(error)throw error;return {records:data||[]};}
 if(action==='records.create'){const {data,error}=await supabase.from('portal_records').insert({collection,value:args.value}).select('id').single();if(error)throw error;return {id:data.id};}
 if(action==='records.replace'){const {error}=await supabase.from('portal_records').update({value:args.value,updated_at:new Date().toISOString()}).eq('id',args.id).eq('collection',collection);if(error)throw error;return {id:args.id};}
 if(action==='records.delete'){const {error}=await supabase.from('portal_records').delete().eq('id',args.id).eq('collection',collection);if(error)throw error;return {id:args.id};}
 throw new Error('Unsupported Supabase data action');
}
async function list(c:string){try{const d=await api('records.list',{collection:c});return d.records||[]}catch{return[]}}
async function createRec(c:string,value:any){return api('records.create',{collection:c,value,idempotency_key:Math.random().toString(36).slice(2)+Date.now()})}
async function replaceRec(c:string,id:string,value:any){return api('records.replace',{collection:c,id,value})}
async function delRec(c:string,id:string){return api('records.delete',{collection:c,id})}

