function SupportBox({onPledge,compact}:{onPledge?:any,compact?:boolean}){
 const [amount,setAmount]=useState(500); const [custom,setCustom]=useState(''); const [purpose,setPurpose]=useState('Donation'); const [name,setName]=useState(''); const [phone,setPhone]=useState(''); const [done,setDone]=useState<any>(null); const [busy,setBusy]=useState(false);
 const finalAmt=custom?+custom:amount;
 const submit=async()=>{
   if(!name.trim()||!phone.trim()||!finalAmt) return;
   setBusy(true);
   const ref='SUP-'+Math.random().toString(36).slice(2,8).toUpperCase();
   const rec={name:name.trim(),phone:phone.trim(),amount:finalAmt,purpose,ref,date:new Date().toLocaleDateString()};
   try{ await createRec('support',rec); if(onPledge) onPledge(rec); setDone(rec);}catch(e:any){ setDone({...rec,error:e.message});}
   setBusy(false);
 };
 return <div className="rounded-3xl p-5 shadow-xl border-2" style={{background:'linear-gradient(135deg,#0A1F14,#0B5D2E)',borderColor:GOLD,color:'#fff'}}>
  <div className="flex items-center gap-2"><HandCoins color={GOLD}/><h3 className="font-black text-lg">Support Us Through M-Pesa — Pochi La Biashara</h3></div>
  <p className="text-sm mt-1 text-white/90"><b>Pochi La Biashara: {WHATSAPP}</b> &nbsp;OR&nbsp; <b>{CALL}</b></p>
  <p className="text-xs mt-2 bg-black/30 rounded-xl p-3">Go to M-Pesa &gt; Lipa na M-Pesa &gt; Pochi La Biashara &gt; Enter {WHATSAPP} or {CALL} &gt; Enter amount &gt; Enter your M-Pesa PIN</p>
  <p className="text-xs font-black mt-2" style={{color:GOLD}}>Membership, tickets, donations, sponsorship and ANY money is sent through the SAME numbers: {WHATSAPP} or {CALL}</p>
  <div className="flex flex-wrap gap-2 mt-3">{[100,200,500,1000,5000].map(v=><button key={v} onClick={()=>{setAmount(v);setCustom('')}} className={`px-3 py-1.5 rounded-full text-sm font-black ${finalAmt===v?'text-black':'bg-white/15 text-white'}`} style={finalAmt===v?{background:GOLD}:{}}>{v}</button>)}</div>
  <div className="grid sm:grid-cols-2 gap-2 mt-3">
   <input value={custom} onChange={e=>setCustom(e.target.value)} placeholder="Custom amount KES" type="number" className="p-2.5 rounded-xl bg-white text-black w-full"/>
   <select value={purpose} onChange={e=>setPurpose(e.target.value)} className="p-2.5 rounded-xl bg-white text-black w-full"><option>Donation</option><option>Membership</option><option>Ticket</option><option>Sponsorship</option><option>Academy</option></select>
   <input value={name} onChange={e=>setName(e.target.value)} placeholder="Your name" className="p-2.5 rounded-xl bg-white text-black w-full"/>
   <input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="Phone e.g. 07..." className="p-2.5 rounded-xl bg-white text-black w-full"/>
  </div>
  <button disabled={busy||!name||!phone||!finalAmt} onClick={submit} className="w-full mt-3 py-3 rounded-full font-black text-black disabled:opacity-50" style={{background:GOLD}}>{busy?'Recording...':'I Have Sent — Record My Support'}</button>
  <div className="flex gap-2 mt-2"><a href={WA_LINK} target="_blank" rel="noopener" className="flex-1 text-center py-2 rounded-full font-bold text-white text-sm" style={{background:'#25D366'}}>Confirm on WhatsApp</a><a href={CALL_LINK} className="flex-1 text-center py-2 rounded-full font-bold bg-white text-black text-sm">Call {CALL}</a></div>
  {done&&<div className="mt-3 p-3 rounded-2xl bg-white text-black text-center"><Check className="mx-auto" color={G}/><b>Asante! Thank you, {done.name}!</b><p className="text-sm">KES {done.amount?.toLocaleString()} • {done.purpose} • Ref: <b>{done.ref}</b></p><p className="text-xs opacity-70">We have recorded your support pledge for Admin. Keep your M-Pesa message.</p>{done.error&&<p className="text-xs text-red-600">{done.error}</p>}</div>}
  <p className="text-[11px] mt-2 text-white/70">Pay via Pochi La Biashara {WHATSAPP} / {CALL}</p>
 </div>
}

